<template>
 <section class="server-monitor setting-card">
  <div class="monitor-heading"><div><h3>运行状态</h3><p>CPU、内存、磁盘与网络 · 每 {{ metrics.interval_seconds||5 }} 秒自动刷新</p></div><el-button :icon="Refresh" :loading="loading" @click="refresh">重新检查</el-button></div>
  <el-alert v-if="error" :title="error" type="error" :closable="false" show-icon/>
  <el-alert v-for="(warning,i) in metrics.warnings||[]" :key="i" :title="warning" type="warning" :closable="false" show-icon/>
  <div class="monitor-service"><span><i :class="health.status==='ok'?'good':'bad'"/>工作台服务：{{ health.status?health.status==='ok'?'运行正常':'连接异常':'检查中' }}</span><span><i :class="health.database==='ok'?'good':'bad'"/>数据连接：{{ health.database?health.database==='ok'?'连接正常':'暂不可用':'检查中' }}</span><span class="muted">{{ sampledTime }}</span></div>
  <template v-if="latest">
   <div class="monitor-scope"><el-tag :type="latest.scope==='host'?'success':'warning'">{{ latest.scope==='host'?'服务器整机':'容器运行环境' }}</el-tag><strong>{{ latest.hostname }}</strong><span class="secondary">{{ latest.environment }}</span><el-tag v-if="metrics.stale" type="danger">采集已中断</el-tag></div>
   <p v-if="latest.environment==='WSL2'" class="monitor-hint">当前监控 WSL Linux 环境，数值不是 Windows 整机指标。部署到云端后显示云服务器数据。</p>
   <p v-if="latest.scope==='container'" class="monitor-hint">当前为容器的 CPU、内存和网络指标；磁盘为所挂载文件系统的共享容量。宿主机整机指标需启用随项目提供的采集器。</p>
   <div class="metric-grid">
    <div class="metric-tile"><span class="metric-label">CPU 使用率</span><div class="metric-number">{{ percentage(latest.cpu?.percent) }}</div><el-progress :percentage="clamp(latest.cpu?.percent)" :show-text="false" :color="tone(latest.cpu?.percent)"/><small>{{ latest.cpu?.capacity_cores }} {{ latest.scope==='container'?'核配额／可用核数':'个逻辑核心' }}</small></div>
    <div class="metric-tile"><span class="metric-label">{{ latest.scope==='container'?'容器内存':'内存使用率' }}</span><div class="metric-number">{{ percentage(latest.memory?.percent) }}</div><el-progress :percentage="clamp(latest.memory?.percent)" :show-text="false" :color="tone(latest.memory?.percent)"/><small>{{ bytes(latest.memory?.used) }} / {{ bytes(latest.memory?.total) }}</small></div>
    <div class="metric-tile"><span class="metric-label">系统磁盘使用率</span><div class="metric-number">{{ percentage(latest.disks?.[0]?.percent) }}</div><el-progress :percentage="clamp(latest.disks?.[0]?.percent)" :show-text="false" :color="tone(latest.disks?.[0]?.percent)"/><small>可用 {{ bytes(latest.disks?.[0]?.free) }} / {{ bytes(latest.disks?.[0]?.total) }}</small></div>
    <div class="metric-tile"><span class="metric-label">网络实时速率</span><div class="network-line"><span>接收</span><strong>{{ bytes(latest.network?.receive_bps) }}/s</strong></div><div class="network-line"><span>发送</span><strong>{{ bytes(latest.network?.send_bps) }}/s</strong></div><small>累计接收 {{ bytes(latest.network?.received_bytes) }} · 发送 {{ bytes(latest.network?.sent_bytes) }}</small></div>
   </div>
   <div v-if="notices.length" class="resource-notices"><el-tag v-for="notice in notices" :key="notice" type="warning">{{ notice }}</el-tag></div>
   <dl class="monitor-facts"><div><dt>系统运行时长</dt><dd>{{ duration(latest.uptime_seconds) }}</dd></div><div><dt>系统负载（1 / 5 / 15 分钟）</dt><dd>{{ latest.load_average?.map((n:number)=>n.toFixed(2)).join(' / ')||'当前环境不提供系统负载' }}</dd></div><div><dt>交换空间 Swap</dt><dd>{{ latest.swap?`${bytes(latest.swap.used)} / ${bytes(latest.swap.total)}`:'当前环境暂不提供' }}</dd></div><div><dt>磁盘读 / 写速率</dt><dd>{{ latest.disk_io?`${bytes(latest.disk_io.read_bps)}/s · ${bytes(latest.disk_io.write_bps)}/s`:'—' }}</dd></div><div><dt>工作台进程</dt><dd>已运行 {{ duration(metrics.api_uptime_seconds) }} · 内存 {{ bytes(metrics.api_memory_bytes) }}</dd></div></dl>
   <div v-if="metrics.history?.length>1" class="monitor-trend"><h4>最近 15 分钟趋势</h4><ServerMetricsTrend :history="metrics.history"/><p class="monitor-hint">仅保留采集器本次启动后的最近 180 次采样，不写入业务数据库。</p></div><p v-else class="monitor-hint">CPU 和网络速率需连续采样；趋势将在下一次采样后显示。</p>
   <details v-if="latest.disks?.length>1"><summary>其他存储磁盘</summary><div v-for="disk in latest.disks.slice(1)" :key="disk.label" class="disk-row"><span>{{ disk.label }}</span><span>{{ percentage(disk.percent) }} · 可用 {{ bytes(disk.free) }} / {{ bytes(disk.total) }}</span></div></details>
   <p v-for="(note,i) in latest.notes||[]" :key="i" class="monitor-hint">{{ note }}</p>
  </template>
  <div v-else class="monitor-hint">正在准备首次服务器采样…</div>
  <div class="monitor-bottom"><span>北京时间 · Asia/Shanghai</span><span>{{ origin }}</span></div>
 </section>
</template>
<script setup lang="ts">
import {computed,defineAsyncComponent,onMounted,onUnmounted,ref} from 'vue'
import {Refresh} from '@/icons'
import {http,apiError} from '@/api/client'
const ServerMetricsTrend=defineAsyncComponent(()=>import('@/components/ServerMetricsTrend.vue'))
const metrics=ref<any>({}),health=ref<any>({}),loading=ref(false),error=ref(''),origin=location.origin
const latest=computed(()=>metrics.value.latest)
const sampledTime=computed(()=>latest.value?.sampled_at?'采样于 '+new Date(latest.value.sampled_at).toLocaleTimeString('zh-CN',{hour12:false,timeZone:'Asia/Shanghai'}):'采样准备中')
function bytes(v:any){if(v===null||v===undefined||!Number.isFinite(Number(v)))return '—';const n=Math.max(0,Number(v)),units=['B','KB','MB','GB','TB'];const i=n?Math.max(0,Math.min(4,Math.floor(Math.log(n)/Math.log(1024)))):0;return (n/1024**i).toLocaleString('zh-CN',{maximumFractionDigits:i?1:0})+' '+units[i]}
function percentage(v:any){return v===null||v===undefined?'—':Number(v).toFixed(1)+'%'}
function clamp(v:any){return Math.min(100,Math.max(0,Number(v)||0))}
function tone(v:any){return Number(v)>=90?'#d64545':Number(v)>=80?'#bd7a16':'#2383e2'}
function duration(v:any){if(v===null||v===undefined)return '—';const s=Math.floor(v);return `${Math.floor(s/86400)} 天 ${Math.floor(s/3600)%24} 小时 ${Math.floor(s/60)%60} 分`}
const notices=computed(()=>{const s=latest.value;if(!s||metrics.value.stale)return [];const out=[];if(s.cpu?.percent>=85)out.push('CPU 使用率较高');if(s.memory?.percent>=85)out.push('内存使用率较高');if(s.disks?.some((d:any)=>d.percent>=85))out.push('磁盘空间偏紧');return out})
let timer:number|undefined,active=true,controller:AbortController|undefined
async function refresh(){if(!active||document.hidden||loading.value)return;window.clearTimeout(timer);loading.value=true;controller=new AbortController();try{const results=await Promise.allSettled([http.get('/system/metrics',{signal:controller.signal,timeout:10000}),http.get('/health',{signal:controller.signal,timeout:10000})]);if(!active)return;const [m,h]=results;const failures=[];if(m.status==='fulfilled')metrics.value=m.value.data;else failures.push('指标刷新失败：'+apiError(m.reason).message);if(h.status==='fulfilled')health.value=h.value.data;else{health.value={status:'error',database:'error'};failures.push('服务检查失败：'+apiError(h.reason).message)}error.value=failures.join('；')}finally{loading.value=false;if(active&&!document.hidden)timer=window.setTimeout(refresh,5000)}}
function visibility(){if(document.hidden)window.clearTimeout(timer);else void refresh()}
onMounted(()=>{document.addEventListener('visibilitychange',visibility);void refresh()})
onUnmounted(()=>{active=false;controller?.abort();window.clearTimeout(timer);document.removeEventListener('visibilitychange',visibility)})
</script>
<style scoped>
.server-monitor{display:grid;gap:16px}.monitor-heading{display:flex;align-items:center;justify-content:space-between;gap:16px}.monitor-heading h3{margin:0 0 7px;font-size:16px}.monitor-heading p{margin:0;color:var(--wb-text-secondary);font-size:12px}.monitor-service,.monitor-scope,.resource-notices{display:flex;gap:12px;align-items:center;flex-wrap:wrap;font-size:12px}.monitor-service{border-bottom:1px solid var(--wb-border);padding-bottom:16px}.monitor-service>span{display:flex;align-items:center;gap:6px}.monitor-service i{width:7px;height:7px;border-radius:50%;display:inline-block}.good{background:var(--el-color-success)}.bad{background:var(--el-color-danger)}.monitor-service>.muted{margin-left:auto}.monitor-scope strong{font-size:13px}.monitor-hint{font-size:12px;line-height:1.8;color:var(--wb-text-secondary);margin:0}.metric-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.metric-tile{border:1px solid var(--wb-border);border-radius:8px;padding:16px;min-width:0;background:var(--wb-surface-subtle)}.metric-label{font-size:12px;color:var(--wb-text-secondary)}.metric-number{font-size:28px;font-weight:650;margin:12px 0 14px;font-variant-numeric:tabular-nums}.metric-tile small{display:block;font-size:11px;line-height:1.8;margin-top:12px;color:var(--wb-text-secondary);overflow-wrap:anywhere}.network-line{display:flex;justify-content:space-between;gap:6px;margin-top:14px;font-size:12px}.network-line>span{color:var(--wb-text-secondary)}.network-line strong{font-size:14px;white-space:nowrap;font-variant-numeric:tabular-nums}.monitor-facts{display:grid;grid-template-columns:1fr 1fr;gap:0 24px;margin:0;font-size:12px}.monitor-facts>div{display:flex;justify-content:space-between;gap:12px;border-bottom:1px solid var(--wb-border);padding:13px 0}.monitor-facts dt{color:var(--wb-text-secondary)}.monitor-facts dd{margin:0;text-align:right;font-variant-numeric:tabular-nums}.monitor-trend h4{font-size:13px;margin:8px 0 12px}.monitor-bottom{display:flex;justify-content:space-between;gap:12px;font-size:11px;color:var(--wb-text-secondary);border-top:1px solid var(--wb-border);padding-top:16px;overflow-wrap:anywhere}.disk-row{display:flex;justify-content:space-between;font-size:12px;padding:12px 0;border-bottom:1px solid var(--wb-border)}summary{font-size:12px;cursor:pointer}@media(max-width:1200px){.metric-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.monitor-facts{grid-template-columns:1fr}}@media(max-width:600px){.metric-grid{grid-template-columns:1fr}.monitor-service>.muted{margin-left:0}.monitor-heading{align-items:flex-start}.monitor-bottom{flex-direction:column}.monitor-facts>div{flex-wrap:wrap}.monitor-facts dd{text-align:left}.network-line strong{font-size:16px}}
</style>